function serviceDetail(s){return `<div class="detail-title">${logo(s.id)}<div style="flex:1"><h3>${s.name}</h3><p>${s.subtitle}</p></div><span class="${s.running?'good-text':'bad-text'} tiny">● ${s.running?'В сети':'Остановлен'}</span></div><div class="btnrow"><button class="action primary" data-action="open-service" data-id="${s.id}">${I('external')} Открыть</button><button class="action ${s.running?'danger':'good'}" data-action="toggle-service" data-id="${s.id}">${I(s.running?'pause':'play')} ${s.running?'Стоп':'Старт'}</button><button class="action" data-action="restart-service" data-id="${s.id}">${I('refresh')} Рестарт</button></div><div class="tabs">${[['overview','Обзор'],['logs','Логи'],['config','Compose']].map(([a,b])=>`<button class="tab ${a===state.detailTab?'active':''}" data-tab="${a}">${b}</button>`).join('')}</div>${state.detailTab==='overview'?`<div class="details"><div><label>CPU</label><strong>${s.running?s.cpu:0}%</strong>${spark(s.cpu,'#35b8ff')}</div><div><label>Оперативная память</label><strong>${s.running?s.ram:0} МБ</strong>${spark(s.ram/100,'#b17bff')}</div><div><label>Группа</label><strong>${s.group}</strong></div><div><label>Аптайм</label><strong>${s.running?s.uptime:'—'}</strong></div><div><label>Порт</label><strong>${s.port}</strong></div><div><label>Состояние</label><strong class="${s.running?'good-text':'bad-text'}">${s.running?'Healthy':'Stopped'}</strong></div></div><h4 class="micro-head">Нагрузка за сутки</h4>${chart(s.cpu,'#2ac4ff','#9d57fc',100)}`:state.detailTab==='logs'?`<div class="logs"><span class="log-ok">[INFO] ${s.name} стартовал успешно</span>\n[INFO] healthcheck passed\n[INFO] Listening on :${s.port}\n[INFO] Scheduled task completed\n<span class="log-ok">[INFO] All systems operational</span>\n[INFO] Это демонстрационные строки журнала</div>`:`<div class="logs">services:\n  ${s.id}:\n    image: demo/${s.id}:latest\n    restart: unless-stopped\n    # Только макет, не реальный Compose\n    ports:\n      - "${s.port}:${s.port}"</div>`}<div class="notice" style="margin-top:12px">Все действия на этой странице симулируются. Подключение к Docker Engine появится на этапе backend.</div>`}
function monitoringPage(){return `${heading('Мониторинг','Живая телеметрия, аптайм, здоровье сервисов и уведомления.')}<div class="grid big-stat-row">${[['Загрузка CPU','18%','cpu','↓ 12% за час'],['ОЗУ','42%','ram','3,4 / 8 ГБ'],['Диск','36%','disk','360 / 1000 ГБ'],['Температура','48°C','activity','CPU · Норма'],['Сеть','42 Мбит/с','network','↓ 8 · ↑ 4 Мбит/с'],['Тревоги','0','bell','Нет критичных']].map((x,i)=>stat(...x,i+2)).join('')}</div><div class="toolbar"><div class="toolbar-group"><strong>Графики производительности</strong><span class="muted tiny">· Демо-телеметрия</span></div><div class="toolbar-group">${['1ч','24ч','7д','30д'].map(t=>`<button class="pill ${state.chartRange===t?'active':''}" data-range="${t}">${t}</button>`).join('')}</div></div><div class="grid three-col">${[['CPU по ядрам',3,'#25caff','#9e71ff'],['Оперативная память',5,'#b36bff','#2bdeff'],['Дисковая активность',7,'#25e6b5','#26b6ff'],['Сетевой трафик',9,'#20b5ff','#cb6cff'],['Задержка запросов',11,'#ab72fa','#2bcaff'],['Здоровье контейнеров',13,'#27e2b6','#4470ff']].map(([title,seed,a,b])=>`<div class="glass panel">${head(title)}<div class="chart-legend"><span><i style="background:${a}"></i>${title.split(' ')[0]}</span><span><i style="background:${b}"></i>Среднее</span></div>${chart(seed+(state.chartRange.length*3),a,b,155)}<div class="row-split tiny muted"><span>${state.chartRange} назад</span><span>Сейчас</span></div></div>`).join('')}</div><div class="grid three-col" style="margin-top:10px"><div class="glass panel">${head('Стабильность и SLA')}<div class="uptime-circles">${['99.98%','100%','99.95%'].map((t,i)=>`<div class="circle"><div class="circle-inner">${t}<small>${['Аптайм','Доступность','Бэкапы'][i]}</small></div></div>`).join('')}</div></div><div class="glass panel">${head('Состояние сервисов','services')}<div class="service-grid" style="grid-template-columns:repeat(2,1fr)">${services.slice(1,9).map((s,i)=>`<button class="service-small" style="min-height:64px" data-service="${s.id}"><div class="service-small-title">${logo(s.id)}<span>${s.name}<br><small><span class="online-dot"></span>Online</small></span></div></button>`).join('')}</div></div><div class="glass panel">${head('Журнал инцидентов')}<div class="activity-row"><span class="good-text">●</span><span>Все критичные метрики в норме</span><time>Сейчас</time></div>${eventList()}</div></div><div class="glass panel" style="margin-top:10px">${head('Последние логи')}<div class="logs"><span class="log-ok">20:47:31  [INFO]  immich</span>  Background job completed\n20:46:18  [INFO]  tailscale  Device connected\n20:40:52  [INFO]  hindsight  Index updated\n20:38:23  [INFO]  docker  Containers healthy\n20:30:02  [INFO]  duplicati  Backup verified</div></div>`}
